 [Serializable]public class Probe {public string state;public Vector2 uv;public Vector3 worldPoint,geometryNormal,tangent,bitangent,lightDirection,gpuShadingNormal;public float gpuNDotL,cpuCheckNDotL;public int meshVertexCount,meshTriangleCount;public Vector3 screenPoint,normalScreenEnd,geometryNormalScreenEnd,lightScreenEnd;}
 [Serializable]public class Frame{public string id,kind;public int frame;public float time,normalStrength,lightAngle,cameraAngle;public int panelVertices,panelTriangles,spriteVertices,spriteTriangles;public Vector3 cameraPosition,lightDirection;public Vector3[]meshScreenCorners;public Probe probe,offProbe;}
 [Serializable]public class Report{public string unity,renderPipeline="Built-in, our executable Lambert normal-mapping shader",sourceKind="our-implementation",normalConvention="T=x, B=y, N=surface outward; baked sprite basis=camera.right/camera.up/-camera.forward",spriteBake="one128x128pose, no AA, RGBA colour plus Linear camera-facing normal RGB, matching alpha, point filtering";public List<Frame>frames=new List<Frame>();public string[]savedScenes;public int knightSourceTriangles;}
 static Job job;static Camera cam;static Light lamp;static NormalMapDemonstration demo;static Material wallMat,spriteMat,sourceMat,guideMat;static GameObject wall,knight,sprite;static Mesh panelMesh,spriteMesh;static Texture2D colourBake,normalBake;static RenderTexture rt;static Report report;static GameObject arrows;
 static void Layer(GameObject obj,int layer){foreach(var tr in obj.GetComponentsInChildren<Transform>(true))tr.gameObject.layer=layer;}
 static void Arrow(string name,Vector3 point,Vector3 direction,Color colour){
  var g=new GameObject(name);g.layer=8;g.transform.SetParent(arrows.transform);var lr=g.AddComponent<LineRenderer>();if(!guideMat)guideMat=new Material(Shader.Find("Sprites/Default"));lr.sharedMaterial=guideMat;lr.startColor=colour;lr.endColor=colour;lr.startWidth=.028f;lr.endWidth=.028f;lr.numCapVertices=3;lr.useWorldSpace=true;
  var end=point+direction.normalized*.9f;var side=Vector3.Cross(direction,cam.transform.forward).normalized*.1f;var head=end-direction.normalized*.17f;lr.positionCount=5;lr.SetPositions(new[]{point,end,head+side,end,head-side});
 }
 static void ShowNormals(Probe probe,bool geometryOnly=false){arrows=new GameObject("Verified normal directions — display length only");Arrow("Geometry normal N",probe.worldPoint,probe.geometryNormal,Color.white);if(!geometryOnly){Arrow("GPU shading normal",probe.worldPoint,probe.gpuShadingNormal,new Color(.30f,1,.56f));Arrow("Surface toward light",probe.worldPoint,probe.lightDirection,new Color(1,.79f,.25f));}}
 static Color Hex(string v){ColorUtility.TryParseHtmlString(v,out var c);return c;}
 static Material Mat(string name,Color colour){var path=Root+"/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Yamyam/NormalMapLesson"));AssetDatabase.CreateAsset(m,path);}m.shader=Shader.Find("Yamyam/NormalMapLesson");m.color=colour;return m;}
 static void Folder(string suffix){Directory.CreateDirectory(Root+"/"+suffix);}
 static Mesh Quad(string name,float size){var path=Root+"/Meshes/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!m){m=new Mesh();m.name=name;AssetDatabase.CreateAsset(m,path);}float q=size/2;m.vertices=new[]{new Vector3(-q,-q,0),new Vector3(-q,q,0),new Vector3(q,q,0),new Vector3(q,-q,0)};m.uv=new[]{new Vector2(0,0),new Vector2(0,1),new Vector2(1,1),new Vector2(1,0)};m.normals=Enumerable.Repeat(Vector3.back,4).ToArray();m.tangents=Enumerable.Repeat(new Vector4(1,0,0,-1),4).ToArray();m.triangles=new[]{0,1,2,0,2,3};m.RecalculateBounds();return m;}
 static GameObject Surface(string name,Mesh mesh,Material mat,Vector3 point){var g=new GameObject(name);g.transform.position=point;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;return g;}
 static float Height(float u,float v){float ry=v*4;int row=Mathf.FloorToInt(ry);float y=ry-row;float rx=u*4+(row%2)*.5f;float x=rx-Mathf.Floor(rx);float dx=Mathf.Min(x,1-x),dy=Mathf.Min(y,1-y);float sx=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.035f,.12f,dx)),sy=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.035f,.12f,dy));return .07f*sx*sy;}
 static Texture2D BrickNormal(){const int n=1024;var map=new Texture2D(n,n,TextureFormat.RGBA32,false,true);var pixels=new Color[n*n];float delta=1f/n;for(int y=0;y<n;y++)for(int x=0;x<n;x++){float u=(x+.5f)/n,v=(y+.5f)/n;float du=(Height(u+delta,v)-Height(u-delta,v))/(2*delta*PanelSize),dv=(Height(u,v+delta)-Height(u,v-delta))/(2*delta*PanelSize);var normal=new Vector3(-du,-dv,1).normalized;pixels[y*n+x]=new Color(normal.x*.5f+.5f,normal.y*.5f+.5f,normal.z*.5f+.5f,1);}map.SetPixels(pixels);map.Apply();string path=Root+"/Generated/BrickNormal.png";File.WriteAllBytes(path,map.EncodeToPNG());Object.DestroyImmediate(map);Import(path,true,false);return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static void Import(string path,bool normal,bool point){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;importer.sRGBTexture=!normal;importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=!normal;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.filterMode=point?FilterMode.Point:FilterMode.Bilinear;importer.wrapMode=TextureWrapMode.Clamp;importer.maxTextureSize=2048;importer.SaveAndReimport();}
 static Texture2D Read(Camera camera,int size,bool data){var target=new RenderTexture(size,size,24,RenderTextureFormat.ARGB32,data?RenderTextureReadWrite.Linear:RenderTextureReadWrite.sRGB){antiAliasing=1};target.Create();var old=camera.targetTexture;camera.targetTexture=target;camera.Render();var previous=RenderTexture.active;RenderTexture.active=target;var tex=new Texture2D(size,size,TextureFormat.RGBA32,false,data);tex.ReadPixels(new Rect(0,0,size,size),0,0);tex.Apply(false);RenderTexture.active=previous;camera.targetTexture=old;target.Release();Object.DestroyImmediate(target);return tex;}
 static void BakeKnight(){
  var bakeObject=new GameObject("One-pose bake camera");var bakeCamera=bakeObject.AddComponent<Camera>();bakeCamera.enabled=false;bakeCamera.orthographic=true;bakeCamera.orthographicSize=1.35f;bakeCamera.aspect=1;bakeCamera.transform.position=new Vector3(5,1.15f,-6);bakeCamera.transform.LookAt(new Vector3(5,1.15f,0));bakeCamera.clearFlags=CameraClearFlags.SolidColor;bakeCamera.backgroundColor=new Color(0,0,0,0);bakeCamera.allowHDR=false;
  var previousLayer=knight.layer;foreach(var tr in knight.GetComponentsInChildren<Transform>(true))tr.gameObject.layer=30;bakeCamera.cullingMask=1<<30;
  sourceMat.SetVector("_BakeRight",bakeCamera.transform.right);sourceMat.SetVector("_BakeUp",bakeCamera.transform.up);sourceMat.SetVector("_BakeOut",-bakeCamera.transform.forward);
  sourceMat.SetFloat("_OutputMode",4);colourBake=Read(bakeCamera,128,false);File.WriteAllBytes(Root+"/Generated/KnightColour.png",colourBake.EncodeToPNG());Object.DestroyImmediate(colourBake);
  sourceMat.SetFloat("_OutputMode",3);normalBake=Read(bakeCamera,128,true);File.WriteAllBytes(Root+"/Generated/KnightNormal.png",normalBake.EncodeToPNG());Object.DestroyImmediate(normalBake);
  sourceMat.SetFloat("_OutputMode",0);foreach(var tr in knight.GetComponentsInChildren<Transform>(true))tr.gameObject.layer=previousLayer;Object.DestroyImmediate(bakeObject);
  Import(Root+"/Generated/KnightColour.png",false,true);Import(Root+"/Generated/KnightNormal.png",true,true);
 }
 static void Build(){
  GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;PlayerSettings.colorSpace=ColorSpace.Linear;QualitySettings.antiAliasing=1;
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;
  foreach(var f in new[]{"Generated","Materials","Meshes","Scenes"})Folder(f);
  wallMat=Mat("Wall",Hex("#BB8B5D"));wallMat.SetTexture("_BumpMap",BrickNormal());wallMat.SetFloat("_NormalStrength",1);wallMat.SetFloat("_OutputMode",0);
  panelMesh=Quad("WallPanel-four-vertices-two-triangles",PanelSize);wall=Surface("Wall panel — unchanged mesh",panelMesh,wallMat,new Vector3(0,1.9f,0));
  knight=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Kay+"Knight.fbx"));knight.name="CC0 Knight 3D source — one baked Idle pose";if(knight.TryGetComponent<Animator>(out var animator))animator.enabled=false;foreach(var tr in knight.GetComponentsInChildren<Transform>(true))if(tr.name.Contains("Sword")||tr.name.Contains("Shield"))tr.gameObject.SetActive(false);
  var idle=AssetDatabase.LoadAllAssetsAtPath(Kay+"Knight.fbx").OfType<AnimationClip>().First(c=>c.name=="Idle");idle.SampleAnimation(knight,.9f);var renderers=knight.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);float scale=2.2f/bounds.size.y;knight.transform.localScale=Vector3.one*scale;idle.SampleAnimation(knight,.9f);knight.transform.localScale=Vector3.one*scale;bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);knight.transform.position=new Vector3(5-bounds.center.x,-bounds.min.y,0-bounds.center.z);knight.transform.rotation=Quaternion.Euler(0,180,0);
  sourceMat=Mat("Knight source bake",Color.white);sourceMat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Kay+"knight_texture.png");sourceMat.SetFloat("_NormalStrength",0);foreach(var renderer in renderers){renderer.sharedMaterial=sourceMat;if(renderer is SkinnedMeshRenderer skinned)skinned.updateWhenOffscreen=true;}
  report.knightSourceTriangles=renderers.Where(r=>r.gameObject.activeInHierarchy).Sum(r=>r is SkinnedMeshRenderer sr?sr.sharedMesh.triangles.Length/3:r.GetComponent<MeshFilter>()?.sharedMesh.triangles.Length/3??0);
  BakeKnight();spriteMat=Mat("Knight baked sprite",Color.white);spriteMat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Generated/KnightColour.png");spriteMat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Generated/KnightNormal.png"));spriteMat.SetFloat("_NormalStrength",1);spriteMat.SetFloat("_OutputMode",0);spriteMesh=Quad("Sprite-four-vertices-two-triangles",2.7f);sprite=Surface("2D sprite — one colour and normal frame",spriteMesh,spriteMat,new Vector3(8,1.15f,0));Layer(wall,8);Layer(knight,9);Layer(sprite,10);
  lamp=new GameObject("Moving directional light — shader reads its actual direction").AddComponent<Light>();lamp.type=LightType.Directional;lamp.color=Color.white;lamp.intensity=1;lamp.shadows=LightShadows.None;
  demo=new GameObject("Normal mapping test bed controls").AddComponent<NormalMapDemonstration>();demo.wallMaterial=wallMat;demo.spriteMaterial=spriteMat;demo.sourceMaterial=sourceMat;demo.movingLight=lamp;demo.animateLight=false;demo.Apply();
  cam=new GameObject("Test bed camera").AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.orthographicSize=2.4f;cam.aspect=1;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.allowHDR=false;cam.nearClipPlane=.1f;cam.farClipPlane=40;
  rt=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB){antiAliasing=1};rt.Create();cam.targetTexture=rt;
 }
 static void View(Vector3 focus,float angle,float size){cam.orthographicSize=size;var radians=angle*Mathf.Deg2Rad;cam.transform.position=focus+new Vector3(Mathf.Sin(radians)*6,.4f,-Mathf.Cos(radians)*6);cam.transform.LookAt(focus);}
 static void LoadFrozenTestbed(){
  GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;PlayerSettings.colorSpace=ColorSpace.Linear;QualitySettings.antiAliasing=1;
  EditorSceneManager.OpenScene(Root+"/Scenes/Testbed.unity",OpenSceneMode.Single);demo=Object.FindFirstObjectByType<NormalMapDemonstration>();demo.animateLight=false;
  wall=GameObject.Find("Wall panel — unchanged mesh");knight=GameObject.Find("CC0 Knight 3D source — one baked Idle pose");sprite=GameObject.Find("2D sprite — one colour and normal frame");
  wallMat=demo.wallMaterial;spriteMat=demo.spriteMaterial;sourceMat=demo.sourceMaterial;lamp=demo.movingLight;panelMesh=wall.GetComponent<MeshFilter>().sharedMesh;spriteMesh=sprite.GetComponent<MeshFilter>().sharedMesh;
  report.knightSourceTriangles=knight.GetComponentsInChildren<Renderer>().Where(r=>r.gameObject.activeInHierarchy).Sum(r=>r is SkinnedMeshRenderer sr?sr.sharedMesh.triangles.Length/3:r.GetComponent<MeshFilter>()?.sharedMesh.triangles.Length/3??0);
  cam=GameObject.Find("Test bed camera").GetComponent<Camera>();cam.enabled=false;rt=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB){antiAliasing=1};rt.Create();cam.targetTexture=rt;
 }
 static void Place(string kind,float angle){cam.cullingMask=kind.StartsWith("knight")?kind=="knight-source"?1<<9:kind=="knight-pipeline"?(1<<9)|(1<<10):1<<10:1<<8;View(kind.StartsWith("knight")?new Vector3(8,1.15f,0):new Vector3(0,1.9f,0),angle,kind.StartsWith("knight")?1.65f:2.4f);if(kind=="knight-source")View(new Vector3(5,1.15f,0),0,1.65f);if(kind=="knight-pipeline")View(new Vector3(6.5f,1.15f,0),0,2.7f);}
 static void Full(){
  var timeline=JsonUtility.FromJson<Timeline>(File.ReadAllText(job.timeline));if(timeline.frames<1||timeline.sections.Length<1)throw new Exception("Actual audio frame timeline missing");LoadFrozenTestbed();
  foreach(var folder in new[]{"frames","ab-off","ab-on"})Directory.CreateDirectory(Path.Combine(job.output,folder));
  for(int f=0;f<timeline.frames;f++){
   float time=f/60f;var section=timeline.sections.LastOrDefault(s=>time>=s.start)??timeline.sections[0];float u=Mathf.Clamp01((time-section.start)/Mathf.Max(.0001f,section.end-section.start));float ease=u*u*(3-2*u);float light=Mathf.Lerp(section.lightFrom,section.lightTo,ease),angle=Mathf.Lerp(section.angleFrom,section.angleTo,ease);
   demo.normalStrength=section.normalStrength;demo.lightAngle=light;demo.Apply();wallMat.SetFloat("_OutputMode",section.mode);spriteMat.SetFloat("_OutputMode",section.mode);Place(section.kind,angle);
   Probe probe=null,off=null;if(!section.kind.StartsWith("knight")){float saved=wallMat.GetFloat("_OutputMode");probe=ReadProbe(section.id);wallMat.SetFloat("_OutputMode",saved);}
   string basename="frame-"+f.ToString("D5");if(section.kind=="wall-ab"){
    demo.normalStrength=0;demo.Apply();off=ReadProbe(section.id+"-off");SavePicture("ab-off/"+basename);demo.normalStrength=1;demo.Apply();SavePicture("ab-on/"+basename);
   }
   if(section.kind=="wall-normals"||section.kind=="wall-flatnormals")ShowNormals(probe,section.kind=="wall-flatnormals");SavePicture("frames/"+basename);if(arrows){Object.DestroyImmediate(arrows);arrows=null;}
   var corners=panelMesh.vertices.Select(v=>{var p=cam.WorldToScreenPoint(wall.transform.TransformPoint(v));return new Vector3(p.x,H-p.y,p.z);}).ToArray();
   report.frames.Add(new Frame{id=section.id,kind=section.kind,frame=f,time=time,normalStrength=section.kind=="knight-source"?sourceMat.GetFloat("_NormalStrength"):demo.normalStrength,lightAngle=light,cameraAngle=angle,panelVertices=panelMesh.vertexCount,panelTriangles=panelMesh.triangles.Length/3,spriteVertices=spriteMesh.vertexCount,spriteTriangles=spriteMesh.triangles.Length/3,cameraPosition=cam.transform.position,lightDirection=-lamp.transform.forward,meshScreenCorners=corners,probe=probe,offProbe=off});
   if(f%300==0)Debug.Log("NORMAL_MAP_FRAME "+f+" / "+timeline.frames);
  }
  File.WriteAllText(Path.Combine(job.output,"full-readback.json"),JsonUtility.ToJson(report,true));File.WriteAllText(Path.Combine(job.output,"success.json"),"{\"frames\":"+timeline.frames+",\"actualNormalShader\":true,\"frozenSourceAssetsLoaded\":true,\"actualSpriteBake\":true}");
 }
 static Probe ReadProbe(string name){
  var uv=new Vector2(.395f,.44f);var world=wall.transform.TransformPoint(new Vector3((uv.x-.5f)*PanelSize,(uv.y-.5f)*PanelSize,0));var screen=cam.WorldToScreenPoint(world);
  var target=new RenderTexture(W,H,24,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear){antiAliasing=1};target.Create();var old=cam.targetTexture;cam.targetTexture=target;wallMat.SetFloat("_OutputMode",2);cam.Render();var previous=RenderTexture.active;RenderTexture.active=target;var tex=new Texture2D(1,1,TextureFormat.RGBAFloat,false,true);tex.ReadPixels(new Rect(Mathf.Floor(screen.x),Mathf.Floor(screen.y),1,1),0,0);tex.Apply();var value=tex.GetPixel(0,0);Object.DestroyImmediate(tex);RenderTexture.active=previous;cam.targetTexture=old;wallMat.SetFloat("_OutputMode",0);target.Release();Object.DestroyImmediate(target);
  var n=new Vector3(value.r,value.g,value.b);var light=-lamp.transform.forward;float calculated=Mathf.Max(0,Vector3.Dot(n.normalized,light.normalized));if(n.sqrMagnitude<.9f||Mathf.Abs(calculated-value.a)>.004f)throw new Exception("Actual float normal/light readback failed: "+value+" / "+calculated);
  var meshN=wall.transform.TransformDirection(panelMesh.normals[0]).normalized;var tangent=panelMesh.tangents[0];var meshT=wall.transform.TransformDirection(new Vector3(tangent.x,tangent.y,tangent.z)).normalized;var meshB=Vector3.Cross(meshN,meshT)*tangent.w;
  var result=new Probe{state=name,uv=uv,worldPoint=world,geometryNormal=meshN,tangent=meshT,bitangent=meshB,lightDirection=light,gpuShadingNormal=n,gpuNDotL=value.a,cpuCheckNDotL=calculated,meshVertexCount=panelMesh.vertexCount,meshTriangleCount=panelMesh.triangles.Length/3,screenPoint=new Vector3(screen.x,H-screen.y,screen.z)};
  var a=cam.WorldToScreenPoint(world+n*.9f);var b=cam.WorldToScreenPoint(world+Vector3.back*.9f);var c=cam.WorldToScreenPoint(world+light*.9f);result.normalScreenEnd=new Vector3(a.x,H-a.y,a.z);result.geometryNormalScreenEnd=new Vector3(b.x,H-b.y,b.z);result.lightScreenEnd=new Vector3(c.x,H-c.y,c.z);return result;
 }
 static void SavePicture(string name){cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var picture=new Texture2D(W,H,TextureFormat.RGBA32,false);picture.ReadPixels(new Rect(0,0,W,H),0,0);picture.Apply(false);File.WriteAllBytes(Path.Combine(job.output,name+".png"),picture.EncodeToPNG());Object.DestroyImmediate(picture);RenderTexture.active=old;}
 static void Capture(string id,string kind,float strength,float lightAngle,float angle=0,float mode=0){
  demo.normalStrength=strength;demo.lightAngle=lightAngle;demo.Apply();sourceMat.SetVector("_LightDir",-lamp.transform.forward);wallMat.SetFloat("_OutputMode",mode);spriteMat.SetFloat("_OutputMode",mode);
  cam.cullingMask=kind.StartsWith("knight")?kind=="knight-source"?1<<9:kind=="knight-pipeline"?(1<<9)|(1<<10):1<<10:1<<8;
  View(kind.StartsWith("knight")?new Vector3(8,1.15f,0):new Vector3(0,1.9f,0),angle,kind.StartsWith("knight")?1.65f:2.4f);
  if(kind=="knight-source")View(new Vector3(5,1.15f,0),0,1.65f);if(kind=="knight-pipeline")View(new Vector3(6.5f,1.15f,0),0,2.7f);
  Probe probe=null;if(!kind.StartsWith("knight")){float saved=wallMat.GetFloat("_OutputMode");probe=ReadProbe(id);wallMat.SetFloat("_OutputMode",saved);}
  if(kind=="wall-normals")ShowNormals(probe);SavePicture(id);if(arrows){Object.DestroyImmediate(arrows);arrows=null;}report.frames.Add(new Frame{id=id,kind=kind,normalStrength=strength,lightAngle=lightAngle,cameraAngle=angle,panelVertices=panelMesh.vertexCount,panelTriangles=panelMesh.triangles.Length/3,spriteVertices=spriteMesh.vertexCount,spriteTriangles=spriteMesh.triangles.Length/3,cameraPosition=cam.transform.position,lightDirection=-lamp.transform.forward,probe=probe});
 }
 static void SaveVariant(string name,float strength,float mode=0,float angle=0){
  var wm=new Material(wallMat);var sm=new Material(spriteMat);var wp=Root+"/Materials/"+name+"-Wall.mat";var sp=Root+"/Materials/"+name+"-Sprite.mat";
  AssetDatabase.DeleteAsset(wp);AssetDatabase.DeleteAsset(sp);AssetDatabase.CreateAsset(wm,wp);AssetDatabase.CreateAsset(sm,sp);
  wall.GetComponent<Renderer>().sharedMaterial=wm;sprite.GetComponent<Renderer>().sharedMaterial=sm;demo.wallMaterial=wm;demo.spriteMaterial=sm;
  demo.normalStrength=strength;demo.lightAngle=40;demo.Apply();wm.SetFloat("_OutputMode",mode);sm.SetFloat("_OutputMode",0);
  View(name=="05-KnightSpriteBake"?new Vector3(6.5f,1.15f,0):new Vector3(0,1.9f,0),angle,name=="05-KnightSpriteBake"?2.7f:2.4f);
  cam.cullingMask=name=="05-KnightSpriteBake"?(1<<9)|(1<<10):1<<8;
  cam.targetTexture=null;cam.enabled=true;demo.animateLight=true;EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Root+"/Scenes/"+name+".unity");cam.enabled=false;cam.targetTexture=rt;demo.animateLight=false;
  wall.GetComponent<Renderer>().sharedMaterial=wallMat;sprite.GetComponent<Renderer>().sharedMaterial=spriteMat;demo.wallMaterial=wallMat;demo.spriteMaterial=spriteMat;
 }
 public static void Run(){try{var args=Environment.GetCommandLineArgs();job=JsonUtility.FromJson<Job>(File.ReadAllText(args[Array.IndexOf(args,"-normalMapJob")+1]));Directory.CreateDirectory(job.output);report=new Report{unity=Application.unityVersion};if(job.mode=="full"){Full();EditorApplication.Exit(0);return;}if(job.mode!="preview")throw new Exception("Unknown finite capture mode");Build();
  Capture("01-wall-off","wall",0,40);Capture("02-wall-on","wall",1,40);Capture("03-wall-light-left","wall",1,-40);Capture("04-wall-normal-rgb","wall",1,40,0,1);Capture("05-wall-normals-oblique","wall-normals",1,40,45);Capture("06-wall-edge","wall-edge",1,40,82);
  Capture("07-knight-source","knight-source",0,40);Capture("08-knight-colour","knight-colour",0,40,0,4);Capture("09-knight-normal-rgb","knight-normal",1,40,0,1);Capture("10-knight-relit-left","knight-lit",1,-55);Capture("11-knight-relit-right","knight-lit",1,55);Capture("12-knight-pipeline","knight-pipeline",1,40);
  SaveVariant("Testbed",1);SaveVariant("01-NormalOff",0);SaveVariant("02-NormalOn",1);SaveVariant("03-NormalRGB",1,1);SaveVariant("04-Edge",1,0,82);SaveVariant("05-KnightSpriteBake",1);report.savedScenes=new[]{"Testbed","01-NormalOff","02-NormalOn","03-NormalRGB","04-Edge","05-KnightSpriteBake"}.Select(x=>Root+"/Scenes/"+x+".unity").ToArray();AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(job.output,"preview-readback.json"),JsonUtility.ToJson(report,true));File.WriteAllText(Path.Combine(job.output,"success.json"),"{\"states\":12,\"actualNormalShader\":true,\"actualMeshReadback\":true,\"actualSpriteBake\":true}");EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
